      color,
      labelColor: color,
      text: label,
      relationTypeId: relationId,
      dash: "draw",
      size: "m",
      fill: "none",
      bend: 0,
      start: { x: 0, y: 0 },
      end: { x: 0, y: 0 },
      arrowheadStart: "none",
      arrowheadEnd: "arrow",
      labelPosition: 0.5,
      font: "draw",
      scale: 1,
    },
  });

  const newArrow = editor.getShape<DiscourseRelationShape>(arrowId);
  if (!newArrow) return null;

  createOrUpdateArrowBinding(editor, newArrow, sourceId, {
    terminal: "start",
    normalizedAnchor: { x: 0.5, y: 0.5 },
    isPrecise: false,
    isExact: false,
