  createOrUpdateArrowBinding(editor, newArrow, targetId, {
    terminal: "end",
    normalizedAnchor: { x: 0.5, y: 0.5 },
    isPrecise: false,
    isExact: false,
  });

  editor.select(arrowId);

  await persistRelationArrow({ editor, arrow: newArrow, targetId });

