  const filteredData = filterUserRecords(oldData);
  const dataWithFixedShapes = fixShapeIndices(filteredData);

  loadSnapshot(newStore, {
    store: dataWithFixedShapes,
    schema: LEGACY_SCHEMA,
  });

  return newStore.getStoreSnapshot();
};

