content.text:
The script checks both places a relation can be defined (the newer settings props and the older config block) and prints a plain sentence:

```js
(() => {
  const ID = "iFbrUplOp";
  const norm = (v) => Array.isArray(v) ? v.map(norm) : v && typeof v === "object"
    ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k.replace(/^:+/, ""), norm(x)])) : v;
  const nodeName = (id) => {
    const p = window.roamAlphaAPI.pull("[:node/title :block/string]", [":block/uid", id]);
    return (p?.[":node/title"] ?? p?.[":block/string"] ?? id).replace(/^discourse-graph\/nodes\//, "");
  };
  const print = (r, where) => console.log(
    `${ID}: "${nodeName(r.source)}" —${r.label}→ "${nodeName(r.destination)}"` +
    `  (reverse: "${nodeName(r.destination)}" —${r.complement || "?"}→ "${nodeName(r.source)}")  [${where}]`);

  // New props-based settings store: a "Relations" map keyed by relation id inside some block's props.
  const rows = window.roamAlphaAPI.data.q("[:find ?uid ?props :where [?b :block/props ?props] [?b :block/uid ?uid]]");
  for (const [uid, raw] of rows) {
    const stack = [norm(raw)];
    while (stack.length) {
      const o = stack.pop();
      if (!o || typeof o !== "object") continue;
      if (o.Relations?.[ID]) return print(o.Relations[ID], `settings props on block ${uid}`);
      stack.push(...Object.values(o));
    }
  }

  // Legacy config tree: the relation is a block whose text is the label, with Source/Destination/Complement children.
  const b = window.roamAlphaAPI.pull(
    "[:block/string {:block/children [:block/string {:block/children [:block/string]}]}]", [":block/uid", ID]);
  if (b) {
    const kid = (k) => b[":block/children"]?.find((c) => new RegExp(`^${k}$`, "i").test(c[":block/string"]))
      ?.[":block/children"]?.[0]?.[":block/string"];
    return print({ label: b[":block/string"], source: kid("Source"), destination: kid("Destination"),
                   complement: kid("Complement") }, "legacy config block");
  }
  console.log(`${ID}: not found. This relation type was deleted (or the uid is wrong).`);
})();
```

Example output:
```
iFbrUplOp: "Evidence" —Supports→ "Claim"  (reverse: "Claim" —Supported By→ "Evidence")  [settings props on block …]
```

The node type names come from looking up the source and destination node-type uids. If one has been deleted, the raw uid is printed in its place. If nothing is found at all, the canvas's `iFbrUplOp` arrows belong to a relation type that no longer exists. That's one of the cases where v6 has to fall back to its arrow-shape check.

