Paste this into the console with the graph open:

```js
(() => {
  const uid = "sXfGGIdBC";
  const norm = (v) => Array.isArray(v) ? v.map(norm) : v && typeof v === "object"
    ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k.replace(/^:+/, ""), norm(x)])) : v;
  const b = window.roamAlphaAPI.pull(
    "[:block/uid :block/string :node/title :block/props {:block/page [:node/title]}]",
    [":block/uid", uid]);
  if (!b) return console.log(`No block or page with uid ${uid}`);
  const props = norm(b[":block/props"] ?? {});
  console.log(`${uid}: ${b[":node/title"] ? `page "${b[":node/title"]}"` : `block on "${b[":block/page"]?.[":node/title"]}"`}`);
  console.log("text:", b[":block/string"] ?? b[":node/title"]);
  console.log("props:", props);
  console.log(JSON.stringify(props, null, 2));
  window.__props = props;
})();
```

It prints three things:
- Whether the uid is a page or a block (and which page the block is on), plus its text.
- The props as an object you can expand, plus a pretty-printed JSON copy.
- The props saved as `window.__props` for further digging.

If the props turn out to be a canvas, `window.__props["roamjs-query-builder"].tldraw` holds its `store` and `schema`. If they're a reified relation, look at `window.__props["discourse-graph"]` for `sourceUid`, `destinationUid` and `hasSchema`. To copy the JSON to your clipboard, run `copy(JSON.stringify(window.__props, null, 2))` in the console.

